#!/usr/bin/env node
// Generated by npm run spec from scripts/seed.mjs. Edit that file, not this copy.
/* The company-size workspace (KT gap 9; R4 rule 1): the demo workspace in spec/conformance/workspace.json copied until
   it holds at least R4's 30,000 goals in a cycle, every copy a division with ids, people and team names of its own, so
   a rebuild can load what R4 designs for and time its pages, its reads and the week's turn against it. Copied by
   `npm run spec` to spec/rebuild/seed.mjs, so a copy of spec/ carries it. Plain Node, no packages; the same input and
   the same number of copies always write the same files, byte for byte.

     node spec/rebuild/seed.mjs <out-dir>                 the company: enough copies for 30,000 goals
     node spec/rebuild/seed.mjs <out-dir> --copies 3      a smaller one while you work
     node spec/rebuild/seed.mjs <out-dir> --from <workspace.json>

   It writes one JSON line per record, a file per kind (people.jsonl, teams.jsonl, goals.jsonl, checkIns.jsonl,
   decisions.jsonl, requests.jsonl, reviews.jsonl, watches.jsonl, and metrics.jsonl and the module's other kinds), and
   seed.json: the cycle, the moment the demo was built for, how many of each kind, and a SHA-256 of every file, so two
   rebuilds can tell they loaded the same workspace. Copy 0 is the demo itself, ids unchanged; copy n adds `_xn` to
   every id. The cycle is shared: one workspace has one goal year at a time. */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

/** R4's design figure for goals in a cycle: the default number of copies is the fewest that reach it. */
export const COMPANY_GOALS = 30_000;
/** The kinds of record copied, in the order written. A module's kinds follow, as `modules.<id>.<kind>`. */
export const KINDS = ['people', 'teams', 'goals', 'checkIns', 'decisions', 'requests', 'reviews', 'watches'];

const here = path.dirname(fileURLToPath(import.meta.url));
/** Where the demo workspace is: beside this file in spec/ (spec/rebuild/ → spec/conformance/), or from scripts/. */
export function defaultSource() {
  for (const p of [path.join(here, '../conformance/workspace.json'), path.join(here, '../spec/conformance/workspace.json')]) if (fs.existsSync(p)) return p;
  throw new Error('Can’t find spec/conformance/workspace.json: pass --from <workspace.json>.');
}

/** Every module's kinds of record, as [label, rows]. */
const moduleKinds = (w) => Object.entries(w.modules ?? {}).flatMap(([m, kinds]) => Object.entries(kinds).filter(([, rows]) => Array.isArray(rows)).map(([k, rows]) => [`modules.${m}.${k}`, rows]));
const kindsOf = (w) => [...KINDS.map((k) => [k, w[k] ?? []]), ...moduleKinds(w)];

/** Every string in `v` that is one of `ids`, with `suffix` added; walks objects and arrays and leaves the rest. */
function rename(v, ids, suffix) {
  if (typeof v === 'string') return ids.has(v) ? v + suffix : v;
  if (Array.isArray(v)) return v.map((x) => rename(x, ids, suffix));
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, rename(x, ids, suffix)]));
  return v;
}

/** Names of its own for each copy's people: the demo's first names and surnames turned past each other, so a search for
    a name finds a handful of people, as in a real company, not one per division. */
function namer(people) {
  const firsts = people.map((p) => p.name.split(' ')[0]);
  const lasts = people.map((p) => p.name.split(' ').slice(1).join(' ') || p.name);
  return (copy, j) => (copy === 0 ? people[j].name : `${firsts[(j + copy) % firsts.length]} ${lasts[(j * 7 + copy * 13) % lasts.length]}`);
}

/** The records of copy `n`, kind by kind. */
export function copyOf(w, n) {
  const ids = new Set();
  for (const [, rows] of kindsOf(w)) for (const r of rows) if (r && typeof r.id === 'string') ids.add(r.id);
  const name = namer(w.people);
  const out = new Map();
  for (const [kind, rows] of kindsOf(w)) {
    let copied = n === 0 ? rows : rename(rows, ids, `_x${n}`);
    if (n > 0 && kind === 'people') copied = copied.map((p, j) => ({ ...p, name: name(n, j) }));
    if (n > 0 && kind === 'teams') copied = copied.map((t) => ({ ...t, name: `${t.name} (division ${n + 1})` }));
    if (n > 0 && kind === 'reviews') copied = copied.map((r) => ({ ...r, name: `${r.name} (division ${n + 1})` }));
    out.set(kind, copied);
  }
  return out;
}

/** The fewest copies of `w` that hold `goals` goals. */
export const copiesFor = (w, goals = COMPANY_GOALS) => Math.ceil(goals / Math.max(1, w.goals.length));

/** Writes the workspace made of `copies` copies of `w` into `dir`; gives back seed.json's contents. */
export function writeSeed(w, dir, copies = copiesFor(w)) {
  fs.mkdirSync(dir, { recursive: true });
  const files = new Map(kindsOf(w).map(([k]) => [k, { fd: fs.openSync(path.join(dir, `${k}.jsonl`), 'w'), hash: crypto.createHash('sha256'), rows: 0 }]));
  for (let n = 0; n < copies; n++) {
    for (const [kind, rows] of copyOf(w, n)) {
      const f = files.get(kind);
      const text = rows.map((r) => JSON.stringify(r) + '\n').join('');
      fs.writeSync(f.fd, text);
      f.hash.update(text);
      f.rows += rows.length;
    }
  }
  const counts = {}, sha256 = {};
  for (const [k, f] of files) { fs.closeSync(f.fd); counts[k] = f.rows; sha256[`${k}.jsonl`] = f.hash.digest('hex'); }
  const seed = { about: 'A company-size workspace made by spec/rebuild/seed.mjs from the demo workspace: one JSON line per record, a file per kind. See spec/rebuild/scale.md.', builtFor: w.builtFor, copies, cycle: w.cycle, counts, sha256 };
  fs.writeFileSync(path.join(dir, 'seed.json'), JSON.stringify(seed, null, 2) + '\n');
  return seed;
}

function main(argv) {
  const out = argv.find((a, i) => !a.startsWith('--') && !argv[i - 1]?.startsWith('--'));
  if (!out) { process.stderr.write('Usage: node seed.mjs <out-dir> [--copies n] [--from workspace.json]\n'); return 2; }
  const opt = (name) => { const i = argv.indexOf(name); return i >= 0 ? argv[i + 1] : undefined; };
  const w = JSON.parse(fs.readFileSync(opt('--from') ?? defaultSource(), 'utf8'));
  const copies = opt('--copies') ? Number(opt('--copies')) : copiesFor(w);
  if (!Number.isInteger(copies) || copies < 1) { process.stderr.write('--copies takes a whole number, 1 or more.\n'); return 2; }
  const seed = writeSeed(w, out, copies);
  process.stdout.write(`${copies} copies into ${out}: ${Object.entries(seed.counts).map(([k, n]) => `${n.toLocaleString('en-GB')} ${k}`).join(', ')}.\n`);
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
